#### Função para Atualizar Visibilidade do Dropdown

Esta função irá alternar entre mostrar ou ocultar a lista de sugestões quando clicarmos fora dela (`blur`) ou dentro delas (`focus`). Também verificaremos periodicamente quanto tempo já decorreu desde que começamos a digitar até decidirmos manter o dropdown aberto.

```jsx
let timeoutId: number | undefined;

function toggleDropdownVisibility(e: MouseEvent): void {
  if (!document.activeElement?.matches('.dropdown')) {
    setShowDropdown(!isOpen());
  } else {
    clearTimeout(timeoutId);
    timeoutId = window.setTimeout(() => {
      setShowDropdown(true);
    }, 300); // Tempo limite antes de fechar automaticamente após perder foco novamente
  }
}

function closeDropdown(): void {
  setShowDropdown(false);
}

function openDropdown(): void {
  setShowDropdown(true);
}

function isOpen(): boolean {
  return showDropdown === true && document.activeElement !== null && !document.activeElement.matches('[data-test="menu"]');
}
