  text,
  textStyle,
  seeMoreStyle,
  containerStyle,
  seeMoreLabel = 'See more',
}) {
  const [expanded, setExpanded] = useState(false);
  const [hasMore, setHasMore] = useState(false);

  useEffect(() => {
    setExpanded(false);
    setHasMore(false);
  }, [text]);

  const handleMeasure = ({ nativeEvent }) => {
    const nextHasMore = nativeEvent.lines.length > 1;
    setHasMore(current => current === nextHasMore ? current : nextHasMore);
  };

  return (
    <View style={containerStyle}>
      <Text style={[styles.text, textStyle]} numberOfLines={expanded ? undefined : 1}>
