          </Text>
        )}
      </Text>

      {/* Measure the full text at the same available width. */}
      <Text
        style={[styles.text, textStyle, styles.measurement]}
        onTextLayout={handleMeasure}
        accessible={false}
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
      >
        {text}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  text: {
    color: '#333',
    fontSize: 16,
  },
  seeMore: {
    color: '#007AFF',
    fontWeight: '600',
  },
  measurement: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    opacity: 0,
  },
});
```

